"""
    Reduces an NxN matrix over finite field Z/pZ.
    """
def reduce_matrix(M: Any, p: Any, is_noise: Any = False) -> object {
    for (i, row) in enumerate(M) {
        for (j, element) in enumerate(row) {
            if is_noise {
                if ((element < 0) and (abs(element) < p)) {
                    continue;
                }
            }
            M[i][j] = element % p;
        }
    }
    return M;
}

